38	import org.springframework.samples.petclinic.mapper.PetMapper;
39	import org.springframework.samples.petclinic.mapper.VisitMapper;
40	import org.springframework.samples.petclinic.model.Owner;
41	import org.springframework.samples.petclinic.model.Pet;
42	import org.springframework.samples.petclinic.model.Visit;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /** Dedicated audit logger; a successful create emits one line here. */
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
72	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
73	
74	    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
75	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
76	        "mailinator.com", "tempmail.com", "guerrillamail.com");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper) {
90	        this.clinicService = clinicService;
91	        this.ownerMapper = ownerMapper;
92	        this.petMapper = petMapper;
93	        this.visitMapper = visitMapper;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        return withOwner(ownerId, owner ->
115	            new ResponseEntity<>(buildOwnerDto(owner), HttpStatus.OK));
116	    }
117	
118	    /**
119	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
120	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
121	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
122	     */
123	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
124	        Owner owner = this.clinicService.findOwnerById(ownerId);
125	        if (owner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return onFound.apply(owner);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        return createOwner(ownerFieldsDto);
135	    }
136	
137	    /**
138	     * Run the create pipeline for a new owner from its submitted fields and return the response: the
139	     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
140	     * identity, household and per-city gates are applied, the derived registration attributes are
141	     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
142	     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
143	     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
144	     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
145	     * of the create pipeline.
146	     */
147	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        if (!normalizeAndValidateFields(owner)) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
153	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
154	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
155	        }
156	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
157	        owner.setRegistrationDate(registrationDate);
158	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
159	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
160	        }
161	        owner.setHouseholdId(householdId(owner));
162	        owner.setIdentityKey(identityKey(owner));
163	        if (isDuplicate(owner)) {
164	            return new ResponseEntity<>(HttpStatus.CONFLICT);
165	        }
166	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
167	        if (!sharesHousehold && hasExistingHousehold(owner)) {
168	            return new ResponseEntity<>(HttpStatus.CONFLICT);
169	        }
170	        if (countOwnersInCity(owner.getCity()) >= 50) {
171	            return new ResponseEntity<>(HttpStatus.CONFLICT);
172	        }
173	        assignRegistrationAttributes(owner, sharesHousehold);
174	        this.clinicService.saveOwner(owner);
175	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
176	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
177	            owner.getMembershipNumber());
178	        HttpHeaders headers = new HttpHeaders();
179	        headers.setLocation(UriComponentsBuilder.newInstance()
180	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
181	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
182	    }
183	
184	    /**
185	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
186	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
187	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
188	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
189	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
190	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
191	     */
192	    private boolean normalizeAndValidateFields(Owner owner) {
193	        if (!normalizeAddressFields(owner)) {
194	            return false;
195	        }
196	        if (owner.getEmail() != null) {
197	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
198	            if (!EMAIL_PATTERN.matcher(email).matches()) {
199	                return false;
200	            }
201	            if (isDisposableEmailDomain(email)) {
202	                return false;
203	            }
204	            owner.setEmail(email);
205	        }
206	        if (!isPostcodeValidForCity(owner)) {
207	            return false;
208	        }
209	        String telephone = normalizeTelephone(owner.getTelephone());
210	        if (telephone == null) {
211	            return false;
212	        }
213	        owner.setTelephone(telephone);
214	        return true;
215	    }
216	
217	    /**
218	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
219	     * returning whether the owner may proceed to creation. The structured fields are preferred when
220	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
221	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
222	     * composed value (the normalized addressLine1, with a single space and the normalized
223	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
224	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
225	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
226	     * address. This is the single place the owner's address is read, canonicalized and written back,
227	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
228	     */
229	    private boolean normalizeAddressFields(Owner owner) {
230	        String line1 = normalizeAddress(owner.getAddressLine1());
231	        if (!line1.isEmpty()) {
232	            String line2 = normalizeAddress(owner.getAddressLine2());
233	            owner.setAddressLine1(line1);
234	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
235	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
236	            return true;
237	        }
238	        String address = normalizeAddress(owner.getAddress());
239	        if (address.isEmpty()) {
240	            return false;
241	        }
242	        owner.setAddress(address);
243	        return true;
244	    }
245	
246	    /**
247	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
248	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
249	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
250	     */
251	    private static boolean isDisposableEmailDomain(String email) {
252	        int at = email.lastIndexOf('@');
253	        if (at < 0) {
254	            return false;
255	        }
256	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
257	    }
258	
259	    /**
260	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
261	     * computed against the owner population rather than carried on the owner itself (currently the
262	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
263	     * listing intentionally omits these flags.
264	     */
265	    private OwnerDto buildOwnerDto(Owner owner) {
266	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
267	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
268	        return ownerDto;
269	    }
270	
271	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
272	    @Override
273	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
274	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
275	        if (currentOwner == null) {
276	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	        }
278	        currentOwner.setAddress(ownerFieldsDto.getAddress());
279	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
280	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
281	        currentOwner.setCity(ownerFieldsDto.getCity());
282	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
283	        currentOwner.setLastName(ownerFieldsDto.getLastName());
284	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
285	        String email = ownerFieldsDto.getEmail();
286	        if (email != null) {
287	            email = email.trim().toLowerCase(Locale.ROOT);
288	            if (!EMAIL_PATTERN.matcher(email).matches()) {
289	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
290	            }
291	        }
292	        currentOwner.setEmail(email);
293	        this.clinicService.saveOwner(currentOwner);
294	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
295	    }
296	
297	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
298	    @Transactional
299	    @Override
300	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
301	        return withOwner(ownerId, owner -> {
302	            owner.setDeleted(true);
303	            this.clinicService.saveOwner(owner);
304	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
305	        });
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
311	        Owner owner = this.clinicService.findOwnerById(ownerId);
312	        if (owner == null) {
313	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
314	        }
315	        HttpHeaders headers = new HttpHeaders();
316	        Pet pet = petMapper.toPet(petFieldsDto);
317	        owner.setId(ownerId);
318	        pet.setOwner(owner);
319	        pet.getType().setName(null);
320	        this.clinicService.savePet(pet);
321	        PetDto petDto = petMapper.toPetDto(pet);
322	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
323	            .buildAndExpand(pet.getId()).toUri());
324	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
325	    }
326	
327	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
328	    @Override
329	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
330	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
331	        if (currentOwner != null) {
332	            Pet currentPet = this.clinicService.findPetById(petId);
333	            if (currentPet != null) {
334	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
335	                currentPet.setName(petFieldsDto.getName());
336	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
337	                this.clinicService.savePet(currentPet);
338	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
339	            }
340	        }
341	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
342	    }
343	
344	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
345	    @Override
346	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
347	        HttpHeaders headers = new HttpHeaders();
348	        Visit visit = visitMapper.toVisit(visitFieldsDto);
349	        Pet pet = new Pet();
350	        pet.setId(petId);
351	        visit.setPet(pet);
352	        this.clinicService.saveVisit(visit);
353	        VisitDto visitDto = visitMapper.toVisitDto(visit);
354	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
355	            .buildAndExpand(visit.getId()).toUri());
356	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
357	    }
358	
359	
360	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
361	    @Override
362	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
363	        Owner owner = this.clinicService.findOwnerById(ownerId);
364	        if (owner != null) {
365	            Pet pet = owner.getPet(petId);
366	            if (pet != null) {
367	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
368	            }
369	        }
370	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
371	    }
372	
373	    /** Matches a well-formed postcode: exactly 4 digits. */
374	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
375	
376	    /**
377	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
378	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
379	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
380	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
381	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
382	     */
383	    private static boolean isPostcodeValidForCity(Owner owner) {
384	        String postcode = owner.getPostcode();
385	        if (postcode == null) {
386	            return true;
387	        }
388	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
389	            return false;
390	        }
391	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
392	        if (range == null) {
393	            return true;
394	        }
395	        int value = Integer.parseInt(postcode);
396	        return value >= range[0] && value <= range[1];
397	    }
398	
399	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
400	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
401	
402	    /**
403	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
404	     * code are kept when present; otherwise country code '+61' is assumed and a single
405	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
406	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
407	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
408	     * Returns {@code null} when the number cannot form a valid E.164 value.
409	     */
410	    private static String normalizeTelephone(String telephone) {
411	        if (telephone == null) {
412	            return null;
413	        }
414	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
415	        String e164;
416	        if (cleaned.startsWith("+")) {
417	            e164 = cleaned;
418	        } else {
419	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
420	            e164 = "+61" + national;
421	        }
422	        if (!E164_PATTERN.matcher(e164).matches()) {
423	            return null;
424	        }
425	        return hasValidNationalNumberLength(e164) ? e164 : null;
426	    }
427	
428	    /**
429	     * Whether the national number of a well-formed E.164 value has the length required for its
430	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
431	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
432	     */
433	    private static boolean hasValidNationalNumberLength(String e164) {
434	        String countryCode = Owner.countryCodeOf(e164);
435	        if (countryCode == null) {
436	            return true;
437	        }
438	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
439	    }
440	
441	    /**
442	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
443	     * code, membership number, household id, namesake count and household member count. Each is
444	     * derived from the owner's already-normalized fields and the existing owner population, so this
445	     * must run before the owner is saved, while the counts still exclude the owner being created.
446	     *
447	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
448	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
449	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
450	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
451	     */
452	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
453	        owner.setCustomerCode(generateCustomerCode(owner));
454	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
455	        owner.setHouseholdId(householdId(owner));
456	        owner.setNamesakeCount(countNamesakes(owner));
457	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
458	        if (declaredMember) {
459	            owner.setPossibleDuplicate(false);
460	            owner.setPossibleDuplicateOf(null);
461	        } else {
462	            assignPossibleDuplicate(owner);
463	        }
464	    }
465	
466	    /**
467	     * Whether {@code owner} would join an existing household, i.e. some already-registered owner
468	     * resolves to the same {@link #householdId(Owner) householdId} (same last name and postcode).
469	     * Because the household is keyed on (last name, postcode), such a create is a household duplicate
470	     * and is rejected with {@code 409 CONFLICT} unless the request sets {@code sharesHousehold}, in
471	     * which case the owner is created as a declared household member.
472	     */
473	    private boolean hasExistingHousehold(Owner owner) {
474	        return !findHousemates(owner).isEmpty();
475	    }
476	
477	    /**
478	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
479	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's last name
480	     * (compared case-insensitively with collapsed whitespace) and postcode but carries a different
481	     * telephone. Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf}
482	     * to the matching owner's id. Runs before save, against the existing owner population.
483	     */
484	    private void assignPossibleDuplicate(Owner owner) {
485	        Integer matchId = findPossibleDuplicateOf(owner);
486	        owner.setPossibleDuplicate(matchId != null);
487	        owner.setPossibleDuplicateOf(matchId);
488	    }
489	
490	    /**
491	     * The id of an existing owner that shares {@code owner}'s postcode and last name (compared
492	     * case-insensitively with collapsed whitespace) but has a different telephone, or {@code null}
493	     * when there is none. When several match, the lowest id is returned. An owner without a postcode
494	     * never matches.
495	     */
496	    private Integer findPossibleDuplicateOf(Owner owner) {
497	        String postcode = owner.getPostcode();
498	        if (postcode == null) {
499	            return null;
500	        }
501	        String lastName = normalizeHouseholdField(owner.getLastName());
502	        String telephone = owner.getTelephone();
503	        return this.clinicService.findAllOwners().stream()
504	            .filter(existing -> !existing.isDeleted())
505	            .filter(existing -> existing.getId() != null
506	                && postcode.equals(existing.getPostcode())
507	                && normalizeHouseholdField(existing.getLastName()).equals(lastName)
508	                && !telephone.equals(existing.getTelephone()))
509	            .map(Owner::getId)
510	            .min(Integer::compareTo)
511	            .orElse(null);
512	    }
513	
514	    /**
515	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
516	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
517	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
518	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
519	     * region and the (telephone, last name) pair; only when the computed code collides with an
520	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
521	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
522	     */
523	    private String generateCustomerCode(Owner owner) {
524	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
525	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
526	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
527	        String base = owner.getRegion() + "-" + hash8;
528	        return deduplicateCustomerCode(base);
529	    }
530	
531	    /**
532	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
533	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
534	     * {@code n} of 2 or more that yields a code no existing owner carries.
535	     */
536	    private String deduplicateCustomerCode(String base) {
537	        Set<String> existing = this.clinicService.findAllOwners().stream()
538	            .map(Owner::getCustomerCode)
539	            .filter(code -> code != null)
540	            .collect(java.util.stream.Collectors.toSet());
541	        if (!existing.contains(base)) {
542	            return base;
543	        }
544	        int n = 2;
545	        while (existing.contains(base + "-" + n)) {
546	            n++;
547	        }
548	        return base + "-" + n;
549	    }
550	
551	    /**
552	     * The number of existing owners registered in {@code city}, compared case-insensitively
553	     * with collapsed whitespace.
554	     */
555	    private int countOwnersInCity(String city) {
556	        String normalized = normalizeHouseholdField(city);
557	        return (int) this.clinicService.findAllOwners().stream()
558	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
559	            .count();
560	    }
561	
562	    /**
563	     * The effective registration date to store for a new owner: the date supplied on the request
564	     * when present, otherwise the current server date, in either case rolled forward to a business
565	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
566	     * This single point of resolution is what every registration-date-derived value (the stored
567	     * date, the membership number's year segment, the per-day create-limit) is computed from.
568	     */
569	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
570	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
571	        return toBusinessDay(date);
572	    }
573	
574	    /**
575	     * The fixed list of public holidays that a registration date must not fall on. A date landing
576	     * on one of these is rolled forward, exactly as weekends are.
577	     */
578	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
579	        LocalDate.of(2026, 1, 1),
580	        LocalDate.of(2026, 1, 26),
581	        LocalDate.of(2026, 4, 25),
582	        LocalDate.of(2026, 12, 25),
583	        LocalDate.of(2026, 12, 28));
584	
585	    /**
586	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
587	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
588	     * unchanged.
589	     */
590	    private static LocalDate toBusinessDay(LocalDate date) {
591	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
592	                || PUBLIC_HOLIDAYS.contains(date)) {
593	            date = date.plusDays(1);
594	        }
595	        return date;
596	    }
597	
598	    /**
599	     * Build the membership number '<customerCode>-M<YY>' where YY is the
600	     * {@link #membershipYearSegment(LocalDate) fiscal-year segment} of the {@code registrationDate}
601	     * (e.g. 'NSW-1A2B3C4D-M27').
602	     */
603	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
604	        return customerCode + "-M" + membershipYearSegment(registrationDate);
605	    }
606	
607	    /**
608	     * The two-digit year segment stamped into a membership number: the last two digits of the
609	     * fiscal year (starting 1 July) that contains the business-day-adjusted {@code registrationDate},
610	     * zero-padded (e.g. a date of 2026-09-05 falls in fiscal year 2027 -> '27'). Shares the
611	     * fiscal-year rule with {@link Owner#getFiscalYear()} via {@link Owner#fiscalYear(LocalDate)}.
612	     */
613	    private static String membershipYearSegment(LocalDate registrationDate) {
614	        return String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
615	    }
616	
617	    /**
618	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
619	     * last name, compared case-insensitively.
620	     */
621	    private int countNamesakes(Owner owner) {
622	        String firstName = normalizeHouseholdField(owner.getFirstName());
623	        String lastName = normalizeHouseholdField(owner.getLastName());
624	        return (int) this.clinicService.findAllOwners().stream()
625	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
626	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
627	            .count();
628	    }
629	
630	    /**
631	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
632	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
633	     * unusually high daily signup volume.
634	     */
635	    private boolean isBulkSignupWarning() {
636	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
637	    }
638	
639	    /** The number of existing owners whose registration date is {@code date}. */
640	    private int countOwnersRegisteredOn(LocalDate date) {
641	        return (int) this.clinicService.findAllOwners().stream()
642	            .filter(existing -> date.equals(existing.getRegistrationDate()))
643	            .count();
644	    }
645	
646	    /**
647	     * The single derived key all duplicate detection flows through, formed from the owner's
648	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
649	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
650	     * id is derived, so the household segment is empty at that point. Because the telephone is part
651	     * of the key, two owners in the same household with different telephones resolve to different
652	     * keys and are both allowed.
653	     */
654	    private static String identityKey(Owner owner) {
655	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
656	        String email = owner.getEmail() == null ? "" : owner.getEmail();
657	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
658	        return telephone + "|" + email + "|" + household;
659	    }
660	
661	    /**
662	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
663	     * duplicate condition: the previously separate telephone, email and household checks are now all
664	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
665	     * trips it is rejected with {@code 409 CONFLICT}.
666	     */
667	    private boolean isDuplicate(Owner owner) {
668	        String key = owner.getIdentityKey();
669	        return this.clinicService.findAllOwners().stream()
670	            .filter(existing -> !existing.isDeleted())
671	            .map(Owner::getIdentityKey)
672	            .filter(existing -> existing != null)
673	            .anyMatch(key::equals);
674	    }
675	
676	    /** Common street-type abbreviations expanded during address normalization. */
677	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
678	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
679	
680	    /**
681	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
682	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
683	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
684	     * string when {@code address} is null or blank after normalization.
685	     */
686	    private static String normalizeAddress(String address) {
687	        if (address == null) {
688	            return "";
689	        }
690	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
691	        if (collapsed.isEmpty()) {
692	            return "";
693	        }
694	        StringBuilder sb = new StringBuilder(collapsed.length());
695	        for (String token : collapsed.split(" ")) {
696	            if (sb.length() > 0) {
697	                sb.append(' ');
698	            }
699	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
700	        }
701	        return sb.toString();
702	    }
703	
704	    /**
705	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
706	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
707	     */
708	    private static String normalizeHouseholdField(String value) {
709	        if (value == null) {
710	            return "";
711	        }
712	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
713	    }
714	
715	    /**
716	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
717	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
718	     * key rather than re-derived from the underlying fields here, so the household is described in one
719	     * place and every household-keyed value stays consistent with it.
720	     */
721	    private List<Owner> findHousemates(Owner owner) {
722	        String householdId = householdId(owner);
723	        return this.clinicService.findAllOwners().stream()
724	            .filter(existing -> !existing.isDeleted())
725	            .filter(existing -> householdId(existing).equals(householdId))
726	            .toList();
727	    }
728	
729	    /**
730	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
731	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
732	     */
733	    private int countHouseholdMembers(Owner owner) {
734	        return findHousemates(owner).size() + 1;
735	    }
736	
737	    /**
738	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
739	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
740	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
741	     * string standing in for a missing postcode), so housemates always resolve to the same value
742	     * regardless of registration order, and owners sharing a last name and postcode share it
743	     * automatically.
744	     */
745	    private static String householdId(Owner owner) {
746	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
747	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
748	        return sha256Hex(key).substring(0, 12);
749	    }
750	
751	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
752	    private static String sha256Hex(String input) {
753	        try {
754	            byte[] digest = MessageDigest.getInstance("SHA-256")
755	                .digest(input.getBytes(StandardCharsets.UTF_8));
756	            StringBuilder sb = new StringBuilder(digest.length * 2);
757	            for (byte b : digest) {
758	                sb.append(String.format("%02X", b));
759	            }
760	            return sb.toString();
761	        }
762	        catch (NoSuchAlgorithmException e) {
763	            throw new IllegalStateException("SHA-256 not available", e);
764	        }
765	    }
766	}
